4	import 'package:cerne/features/capture/domain/entities/recognition_failure.dart';
5	import 'package:cerne/features/capture/domain/repositories/audio_capture_repository.dart';
6	import 'package:cerne/features/capture/domain/repositories/audio_transcription_repository.dart';
7	import 'package:cerne/features/capture/domain/repositories/photo_capture_repository.dart';
8	import 'package:cerne/features/capture/domain/usecases/confirm_entry_save_usecase.dart';
9	import 'package:cerne/features/capture/domain/usecases/recognize_photo_usecase.dart';
10	import 'package:cerne/features/capture/domain/usecases/save_text_entry_usecase.dart';
11	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
12	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
13	import 'package:cerne/features/entries/domain/entities/entry.dart';
14	import 'package:flutter_bloc/flutter_bloc.dart';
15	
16	const _offlineMessage = 'Sem conexão. Conecte-se à internet para salvar.';
17	const _noSpeechMessage = 'Não foi possível identificar fala no áudio.';
18	const _genericAudioMessage = 'Não foi possível transcrever';
19	const _noTextMessage = 'Não foi possível reconhecer o texto';
20	
21	/// The fixed placeholder sent as `content` for "Salvar só a foto"
22	/// (research.md R3) — a single `const` at this, its one call site.
23	const _photoNoTextPlaceholder = 'Foto registrada sem texto reconhecido.';
