25	/// One screen-scoped bloc for the whole Insertion Modal
26	/// (contracts/insertion-modal-bloc.md) — created fresh by `BlocProvider`
27	/// every time `showModalBottomSheet` opens the modal, which is what makes
28	/// FR-002's "reset every tab... each time the modal is freshly opened" true
29	/// without an explicit reset event.
30	class InsertionModalBloc
31	    extends Bloc<InsertionModalEvent, InsertionModalState> {
32	  InsertionModalBloc({
33	    required this._saveTextEntryUseCase,
34	    required this._audioCaptureRepository,
35	    required this._audioTranscriptionRepository,
36	    required this._confirmEntrySaveUseCase,
37	    required this._photoCaptureRepository,
38	    required this._recognizePhotoUseCase,
39	  }) : super(const InsertionModalTexto()) {
40	    on<TabSelected>(_onTabSelected);
41	    on<TextDraftChanged>(_onTextDraftChanged);
42	    on<SaveTextSubmitted>(_onSaveTextSubmitted);
43	    on<AudioStartRequested>(_onAudioStartRequested);
44	    on<AudioTimerTicked>(_onAudioTimerTicked);
45	    on<AudioStopRequested>(_onAudioStopRequested);
46	    on<AudioReviewTextChanged>(_onAudioReviewTextChanged);
47	    on<AudioSaveConfirmed>(_onAudioSaveConfirmed);
48	    on<PhotoSourceSelected>(_onPhotoSourceSelected);
49	    on<PhotoReviewTextChanged>(_onPhotoReviewTextChanged);
50	    on<PhotoSaveConfirmed>(_onPhotoSaveConfirmed);
51	    on<PhotoSaveWithoutTextRequested>(_onPhotoSaveWithoutTextRequested);
52	    on<RetryRequested>(_onRetryRequested);
53	    on<ModalClosed>(_onModalClosed);
54	  }
55	
56	  final SaveTextEntryUseCase _saveTextEntryUseCase;
57	  final AudioCaptureRepository _audioCaptureRepository;
58	  final AudioTranscriptionRepository _audioTranscriptionRepository;
59	  final ConfirmEntrySaveUseCase _confirmEntrySaveUseCase;
60	  final PhotoCaptureRepository _photoCaptureRepository;
61	  final RecognizePhotoUseCase _recognizePhotoUseCase;
62	
63	  final _closeController = StreamController<void>.broadcast();
64	
65	  /// A one-shot side effect, not a state (FR-011, contracts/
66	  /// insertion-modal-bloc.md) — `InsertionModalPage` listens to this to pop
67	  /// the sheet. There is nothing to render for "success", so it never
68	  /// becomes a dedicated `InsertionModalState` case.
69	  Stream<void> get closeRequests => _closeController.stream;
70	
71	  String _textDraft = '';
72	  String? _pendingAudioPath;
73	  String? _pendingImagePath;
74	  Timer? _audioTicker;
75	
76	  /// Guards against discarding the same recording twice when both the
77	  /// explicit `ModalClosed` handler and `close()`'s disposal-time fallback
78	  /// (for the swipe-down/tap-outside dismissal that bypasses `ModalClosed`)
79	  /// would otherwise race on the same still-recording state.
80	  bool _recordingDiscarded = false;
81	
82	  bool _isAudioAbandonable(InsertionModalState state) =>
83	      state is InsertionModalAudioProcessing ||
84	      state is InsertionModalAudioTranscribed ||
85	      state is InsertionModalAudioSaving ||
86	      state is InsertionModalAudioSaveFailure ||
87	      state is InsertionModalAudioFailure;
88	
89	  bool _isFotoAbandonable(InsertionModalState state) =>
90	      state is InsertionModalFotoProcessing ||
91	      state is InsertionModalFotoReconhecido ||
92	      state is InsertionModalFotoSaving ||
93	      state is InsertionModalFotoSaveFailure ||
94	      state is InsertionModalFotoFailure;
95	
96	  Future<void> _onTabSelected(
97	    TabSelected event,
98	    Emitter<InsertionModalState> emit,
99	  ) async {
100	    final current = state;
101	    if (current is InsertionModalAudioRecording) {
102	      // Switching away mid-recording discards it (Edge Cases) — nothing
103	      // from an abandoned capture may survive (FR-011).
104	      _audioCaptureRepository.discard();
105	      _recordingDiscarded = true;
106	      _stopAudioTicker();
107	      _pendingAudioPath = null;
108	    } else if (_isAudioAbandonable(current)) {
109	      // Leaving any in-flight/reviewed/failed Áudio sub-state abandons the
110	      // held audio and any unsaved review edits (FR-011, data-model.md's
111	      // transition table).
112	      _pendingAudioPath = null;
113	    }
114	
115	    if (_isFotoAbandonable(current)) {
116	      _pendingImagePath = null;
117	    }
118	
119	    switch (event.tab) {
120	      case CaptureTab.texto:
121	        emit(InsertionModalTexto(text: _textDraft));
122	      case CaptureTab.audio:
123	        emit(const InsertionModalAudioIdle());
124	      case CaptureTab.foto:
125	        emit(const InsertionModalFotoCaptura());
126	    }
127	  }
128	
129	  Future<void> _onAudioStartRequested(
130	    AudioStartRequested event,
131	    Emitter<InsertionModalState> emit,
132	  ) async {
133	    if (state is! InsertionModalAudioIdle) return;
134	
135	    final hasPermission = await _audioCaptureRepository.hasPermission();
136	    if (!hasPermission) {
137	      emit(const InsertionModalAudioPermissionDenied());
138	      return;
139	    }
140	    await _audioCaptureRepository.start();
141	    _recordingDiscarded = false;
142	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
143	    _startAudioTicker();
144	  }
145	
146	  void _startAudioTicker() {
147	    _audioTicker?.cancel();
148	    _audioTicker = Timer.periodic(
149	      const Duration(seconds: 1),
150	      (_) => add(const AudioTimerTicked()),
151	    );
152	  }
153	
154	  void _stopAudioTicker() {
155	    _audioTicker?.cancel();
156	    _audioTicker = null;
157	  }
158	
159	  void _onTextDraftChanged(
160	    TextDraftChanged event,
161	    Emitter<InsertionModalState> emit,
162	  ) {
163	    _textDraft = event.text;
164	    emit(InsertionModalTexto(text: event.text));
165	  }
166	
167	  void _onAudioTimerTicked(
168	    AudioTimerTicked event,
169	    Emitter<InsertionModalState> emit,
170	  ) {
171	    final current = state;
172	    if (current is InsertionModalAudioRecording) {
173	      emit(
174	        InsertionModalAudioRecording(
175	          elapsed: current.elapsed + const Duration(seconds: 1),
176	        ),
177	      );
178	    }
179	  }
180	
181	  Future<void> _onSaveTextSubmitted(
182	    SaveTextSubmitted event,
183	    Emitter<InsertionModalState> emit,
184	  ) async {
185	    final current = state;
186	    final text = switch (current) {
187	      InsertionModalTexto(text: final t) => t,
188	      InsertionModalTextoFailure(text: final t) => t,
189	      _ => null,
190	    };
191	    if (text == null || text.trim().isEmpty) return;
192	
193	    emit(InsertionModalTextoSaving(text));
194	    final result = await _saveTextEntryUseCase(text);
195	    result.match(
196	      (failure) => emit(
197	        InsertionModalTextoFailure(text: text, message: failure.message),
198	      ),
199	      (entry) => _completeSave(),
200	    );
201	  }
202	
203	  Future<void> _onAudioStopRequested(
204	    AudioStopRequested event,
205	    Emitter<InsertionModalState> emit,
206	  ) async {
207	    final current = state;
208	    if (current is! InsertionModalAudioRecording) return;
209	
210	    _stopAudioTicker();
211	    final duration = current.elapsed;
212	    final path = await _audioCaptureRepository.stop();
213	    _pendingAudioPath = path;
214	    // No connectivity gate (FR-001, research.md R1) — on-device
215	    // transcription must begin unconditionally on stop.
216	    emit(InsertionModalAudioProcessing(duration: duration));
217	    await _transcribeAudio(path, duration, emit);
218	  }
219	
220	  Future<void> _transcribeAudio(
221	    String audioFilePath,
222	    Duration duration,
223	    Emitter<InsertionModalState> emit,
224	  ) async {
225	    final result = await _audioTranscriptionRepository.transcribe(
226	      audioFilePath,
227	    );
228	
229	    // The user may have switched tabs/closed the modal while transcription
230	    // was running — discard a stale result outright (research.md R6,
231	    // FR-011/User Story 5).
232	    if (state is! InsertionModalAudioProcessing ||
233	        _pendingAudioPath != audioFilePath) {
234	      return;
235	    }
236	
237	    result.match(
238	      (failure) => emit(
239	        InsertionModalAudioFailure(
240	          duration: duration,
241	          message: _recognitionFailureMessage(failure),
242	        ),
243	      ),
244	      (text) =>
245	          emit(InsertionModalAudioTranscribed(text: text, duration: duration)),
246	    );
247	  }
248	
249	  String _recognitionFailureMessage(RecognitionFailure failure) =>
250	      switch (failure) {
251	        EmptyRecognitionResult() => _noSpeechMessage,
252	        TranscriptionError() => _genericAudioMessage,
253	      };
254	
255	  void _onAudioReviewTextChanged(
256	    AudioReviewTextChanged event,
257	    Emitter<InsertionModalState> emit,
258	  ) {
259	    final current = state;
260	    if (current is InsertionModalAudioTranscribed) {
261	      emit(
262	        InsertionModalAudioTranscribed(
263	          text: event.text,
264	          duration: current.duration,
265	        ),
266	      );
267	    } else if (current is InsertionModalAudioSaveFailure) {
268	      emit(
269	        InsertionModalAudioSaveFailure(
270	          text: event.text,
271	          duration: current.duration,
272	          message: current.message,
273	        ),
274	      );
275	    }
276	  }
277	
278	  Future<void> _onAudioSaveConfirmed(
279	    AudioSaveConfirmed event,
280	    Emitter<InsertionModalState> emit,
281	  ) async {
282	    final current = state;
283	    final (text, duration) = switch (current) {
284	      InsertionModalAudioTranscribed(text: final t, duration: final d) => (
285	        t,
286	        d,
287	      ),
288	      InsertionModalAudioSaveFailure(text: final t, duration: final d) => (
289	        t,
290	        d,
291	      ),
292	      _ => (null, null),
293	    };
294	    if (text == null || duration == null || text.trim().isEmpty) return;
295	
296	    emit(InsertionModalAudioSaving(text: text, duration: duration));
297	    final result = await _confirmEntrySaveUseCase(text, EntrySource.audio);
298	    result.match(
299	      (failure) => emit(
300	        InsertionModalAudioSaveFailure(
301	          text: text,
302	          duration: duration,
303	          message: _confirmSaveFailureMessage(failure),
304	        ),
305	      ),
306	      (entry) {
307	        _pendingAudioPath = null;
308	        _completeSave();
309	      },
310	    );
311	  }
312	
313	  Future<void> _onPhotoSourceSelected(
314	    PhotoSourceSelected event,
315	    Emitter<InsertionModalState> emit,
316	  ) async {
317	    final current = state;
318	    if (current is InsertionModalFotoProcessing ||
319	        current is InsertionModalFotoSaving) {
320	      return;
321	    }
322	
323	    String? path;
324	    try {
325	      path = await _photoCaptureRepository.pickImage(event.source);
326	    } catch (_) {
327	      emit(const InsertionModalFotoPermissionDenied());
328	      return;
329	    }
330	
331	    if (path == null) {
332	      emit(const InsertionModalFotoCaptura());
333	      return;
334	    }
335	
336	    _pendingImagePath = path;
337	    emit(InsertionModalFotoProcessing(imagePath: path));
338	    await _recognizePhoto(path, emit);
339	  }
340	
341	  Future<void> _recognizePhoto(
342	    String imageFilePath,
343	    Emitter<InsertionModalState> emit,
344	  ) async {
345	    final result = await _recognizePhotoUseCase(imageFilePath);
346	
347	    // Same stale-result guard as audio (research.md R6).
348	    if (state is! InsertionModalFotoProcessing ||
349	        _pendingImagePath != imageFilePath) {
350	      return;
351	    }
352	
353	    result.match(
354	      (failure) => emit(
355	        InsertionModalFotoFailure(
356	          imagePath: imageFilePath,
357	          message: _photoRecognitionFailureMessage(failure),
358	        ),
359	      ),
360	      // confidence read but never branched on (Clarification 3).
361	      (ocrResult) => emit(
362	        InsertionModalFotoReconhecido(
363	          imagePath: imageFilePath,
364	          text: ocrResult.text,
365	        ),
366	      ),
367	    );
368	  }
369	
370	  String _photoRecognitionFailureMessage(
371	    PhotoRecognitionAttemptFailure failure,
372	  ) => switch (failure) {
373	    PhotoRecognitionOffline() => _offlineMessage,
374	    PhotoRecognitionCallFailed(failure: final f) =>
375	      f is OcrNoTextFailure ? _noTextMessage : f.message,
376	  };
377	
378	  void _onPhotoReviewTextChanged(
379	    PhotoReviewTextChanged event,
380	    Emitter<InsertionModalState> emit,
381	  ) {
382	    final current = state;
383	    if (current is InsertionModalFotoReconhecido) {
384	      emit(
385	        InsertionModalFotoReconhecido(
386	          imagePath: current.imagePath,
387	          text: event.text,
388	        ),
389	      );
390	    } else if (current is InsertionModalFotoSaveFailure) {
391	      emit(
392	        InsertionModalFotoSaveFailure(
393	          imagePath: current.imagePath,
394	          text: event.text,
395	          message: current.message,
396	        ),
397	      );
398	    }
399	  }
400	
401	  Future<void> _onPhotoSaveConfirmed(
402	    PhotoSaveConfirmed event,
403	    Emitter<InsertionModalState> emit,
404	  ) async {
405	    final current = state;
406	    final (imagePath, text) = switch (current) {
407	      InsertionModalFotoReconhecido(imagePath: final p, text: final t) => (
408	        p,
409	        t,
410	      ),
411	      InsertionModalFotoSaveFailure(imagePath: final p, text: final t) => (
412	        p,
413	        t,
414	      ),
415	      _ => (null, null),
416	    };
417	    if (imagePath == null || text == null || text.trim().isEmpty) return;
418	
419	    await _confirmPhotoSave(imagePath, text, emit);
420	  }
421	
422	  Future<void> _onPhotoSaveWithoutTextRequested(
423	    PhotoSaveWithoutTextRequested event,
424	    Emitter<InsertionModalState> emit,
425	  ) async {
426	    final current = state;
427	    if (current is! InsertionModalFotoFailure) return;
428	
429	    // No further OCR call for this capture (FR-008) — saves immediately
430	    // with the fixed placeholder.
431	    await _confirmPhotoSave(current.imagePath, _photoNoTextPlaceholder, emit);
432	  }
433	
434	  Future<void> _confirmPhotoSave(
435	    String imagePath,
436	    String text,
437	    Emitter<InsertionModalState> emit,
438	  ) async {
439	    emit(InsertionModalFotoSaving(imagePath: imagePath, text: text));
440	    final result = await _confirmEntrySaveUseCase(text, EntrySource.photo);
441	    result.match(
442	      (failure) => emit(
443	        InsertionModalFotoSaveFailure(
444	          imagePath: imagePath,
445	          text: text,
446	          message: _confirmSaveFailureMessage(failure),
447	        ),
448	      ),
449	      (entry) {
450	        _pendingImagePath = null;
451	        _completeSave();
452	      },
453	    );
454	  }
455	
456	  String _confirmSaveFailureMessage(ConfirmEntrySaveFailure failure) =>
457	      switch (failure) {
458	        ConfirmEntrySaveOffline() => _offlineMessage,
459	        ConfirmEntrySaveCreationFailed(failure: final f) => f.message,
460	      };
461	
462	  Future<void> _onRetryRequested(
463	    RetryRequested event,
464	    Emitter<InsertionModalState> emit,
465	  ) async {
466	    final current = state;
467	    final audioPath = _pendingAudioPath;
468	    final imagePath = _pendingImagePath;
469	    if (current is InsertionModalAudioFailure && audioPath != null) {
470	      final duration = current.duration;
471	      emit(InsertionModalAudioProcessing(duration: duration));
472	      await _transcribeAudio(audioPath, duration, emit);
473	    } else if (current is InsertionModalFotoFailure && imagePath != null) {
474	      emit(InsertionModalFotoProcessing(imagePath: imagePath));
475	      await _recognizePhoto(imagePath, emit);
476	    }
477	  }
478	
479	  void _onModalClosed(ModalClosed event, Emitter<InsertionModalState> emit) {
480	    if (state is InsertionModalAudioRecording) {
481	      _audioCaptureRepository.discard();
482	      _recordingDiscarded = true;
483	      _stopAudioTicker();
484	    }
485	    // Unconditionally clears every held capture, regardless of which
486	    // Áudio/Foto sub-state is active when the modal closes (FR-011).
487	    _pendingAudioPath = null;
488	    _pendingImagePath = null;
489	  }
490	
491	  void _completeSave() {
492	    if (!_closeController.isClosed) {
493	      _closeController.add(null);
494	    }
495	  }
496	
497	  @override
498	  Future<void> close() {
499	    if (state is InsertionModalAudioRecording && !_recordingDiscarded) {
500	      // `showModalBottomSheet`'s default swipe-down/tap-outside dismissal
501	      // bypasses `ModalClosed` entirely, so this is the only place that
502	      // reliably catches a still-recording mic at disposal time (FR-011).
503	      _audioCaptureRepository.discard();
504	      _recordingDiscarded = true;
505	      _pendingAudioPath = null;
506	    }
507	    _stopAudioTicker();
508	    unawaited(_closeController.close());
509	    return super.close();
510	  }
511	}
