    },
    build: buildBloc,
    seed: () => const InsertionModalAudioRecording(elapsed: Duration.zero),
    act: (bloc) => bloc.add(const AudioStopRequested()),
    expect: () => [
      const InsertionModalAudioProcessing(duration: Duration.zero),
      isA<InsertionModalAudioFailure>(),
    ],
