      bloc.add(const AudioSaveConfirmed());
    },
    wait: const Duration(milliseconds: 60),
    expect: () => [
      const InsertionModalAudioSaving(
        text: 'hello world',
        duration: Duration(seconds: 5),
      ),
    ],
    verify: (_) {
      verify(
        () => confirmEntrySaveUseCase('hello world', EntrySource.audio),
